styles:
.page-post .post-head { padding-top: clamp(140px, 18vh, 220px); }
.page-post .post-head__inner { max-width: 720px; margin-inline: auto; }
.page-post .post-eyebrow { display: inline-block; font-family: var(--font-display); font-weight: 600; font-size: 13px; letter-spacing: .06em; text-transform: uppercase; color: var(--red); border: 1px solid var(--line); border-radius: 999px; padding: 6px 16px; margin-bottom: 22px; }
.page-post .post-tags { display: flex; flex-wrap: wrap; gap: 10px; margin-bottom: 22px; }
.page-post .post-tags span { display: inline-block; font-family: var(--font-display); font-weight: 600; font-size: 13px; letter-spacing: .04em; color: var(--red); border: 1px solid var(--line); border-radius: 999px; padding: 6px 16px; }
.page-post .post-title { font-size: clamp(38px, 5.4vw, 68px); line-height: 1.06; color: var(--grey-900); letter-spacing: -0.01em; }
.page-post .post-meta { margin-top: 22px; display: flex; flex-wrap: wrap; align-items: center; gap: 10px; font-size: 15px; color: var(--grey-700); }
.page-post .post-meta__author { font-family: var(--font-display); font-weight: 600; color: var(--grey-900); }
.page-post .post-meta__dot { width: 3px; height: 3px; border-radius: 50%; background: var(--grey-300); flex: none; }

.page-post .post-cover { max-width: 980px; margin: clamp(34px, 5vw, 60px) auto 0; border-radius: var(--radius-lg); overflow: hidden; background: var(--bg-alt); }
.page-post .post-cover img { width: 100%; height: auto; display: block; }

.page-post .post-body { max-width: 720px; margin-inline: auto; padding-block: clamp(40px, 6vw, 72px); }
.page-post .post-body p { font-size: clamp(17px, 1.2vw, 19px); line-height: 1.85; color: var(--grey-700); margin-bottom: 1.5em; }
.page-post .post-body p:last-child { margin-bottom: 0; }
.page-post .post-body .lead { font-size: clamp(19px, 1.4vw, 22px); line-height: 1.7; color: var(--grey-900); }
.page-post .post-body h2 { font-size: clamp(28px, 3.4vw, 40px); line-height: 1.12; color: var(--red); margin: clamp(40px, 5vw, 64px) 0 .5em; }
.page-post .post-body h3 { font-family: var(--font-display); font-weight: 600; font-size: clamp(20px, 1.9vw, 26px); line-height: 1.2; color: var(--grey-900); margin: clamp(28px, 3.5vw, 44px) 0 .7em; }
.page-post .post-body em { font-style: italic; }
.page-post .post-body strong { color: var(--grey-900); font-weight: 400; }

.page-post .post-back { max-width: 720px; margin: 0 auto; padding-bottom: clamp(50px, 7vw, 90px); }
.page-post .post-back a { display: inline-flex; align-items: center; gap: 12px; font-family: var(--font-display); font-weight: 600; font-size: 16px; color: var(--grey-900); border: 1px solid var(--grey-300); border-radius: 999px; padding: 12px 24px; transition: border-color .3s var(--ease), color .3s var(--ease); }
.page-post .post-back a:hover { border-color: var(--red); color: var(--red); }

@media (max-width: 640px) {
  .page-post .post-head { padding-top: clamp(120px, 22vh, 160px); }
}
